insert into public.modules (module_id, title, grade_class, term, "order", weeks, output, content_standard, performance_standard, unlocked) values ($q$G9-M2$q$, $q$Animation$q$, $q$G9$q$, $q$Term 2$q$, 2, 6, $q$A short animation made from your own hand drawn frames, with the in between frames made by a free AI tool and the final timing, zoom and sound added in a video editor.$q$, null, null, false) on conflict (module_id) do nothing;
insert into public.activities (activity_id, module_id, "order", week, title, competency_code, is_performance_task, lesson_goal, before_hook, watch_for, video_slot, video_candidate, video_preview_note, video_status, video_title, video_channel, video_runtime, video_url, after_bridge, activity_brief, submission_type, tool, ai_note, rubric, rubric_total, sections) values ($q$G9-A2.1$q$, $q$G9-M2$q$, 1, $q$Week 1$q$, $q$The 12 Principles, Part 1: Make It Feel Alive$q$, null, false, $q$I want you to learn the first six principles of animation and to spot at least two of them in an animation you already know.$q$, $q$Think of a bouncing ball. A rubber ball and a steel ball can fall from the same height, but they do not look the same when they hit the floor. One squashes a little. One does not. Animators use a small set of ideas to make drawings feel like they have weight, energy, and life. Those ideas are called the 12 principles of animation. They were collected by the Disney animators Frank Thomas and Ollie Johnston in their book The Illusion of Life. Today we start with the first six.$q$, $q$["When does the object get squashed or stretched, and what does that tell you about how heavy or soft it is?","What small move happens just before a big action?","Where do you look first on the screen, and how did the animator make you look there?"]$q$::jsonb, $q$The 12 principles of animation, an introduction, 5 to 15 minutes, English.$q$, $q$Alan Becker, 12 Principles of Animation series (first video).$q$, $q$Found by web search, not play tested from the build environment. Watch it once before class.$q$, $q$Found by web search. Check before class.$q$, $q$12 Principles of Animation (first video in the series)$q$, $q$Alan Becker$q$, null, $q$https://www.youtube.com/watch?v=uDqjIdI4bF4$q$, $q$So the first six principles are tools for weight, readiness, clarity, and flow. Squash and stretch gives weight. Anticipation warns us. Staging points our eyes. Pose to pose gives control. Follow through lets things settle. Slow in and slow out makes motion feel natural. Next lesson we finish the other six.$q$, $q$Pick any short animation you have seen, a cartoon, a game scene, or an animated ad. In 5 to 7 sentences, name two of today's six principles and describe exactly where you saw each one. Do not retell the story. For example, do not write that the hero jumped. Write that he crouched first (anticipation) and his body stretched in the air (squash and stretch).$q$, $q$Short text$q$, $q$None needed. You only need an animation to think about.$q$, null, $q$[{"criteria":"Names two real principles","points":4},{"criteria":"Points to a specific moment for each","points":3},{"criteria":"Describes how it looks, not the plot","points":3}]$q$::jsonb, 10, $q$[{"type":"read","title":"Warm up: the bouncing ball","minutes":10,"body":"Draw a ball in your mind. Now drop it. A beach ball floats down slowly and barely changes shape. A rubber ball falls fast, flattens when it hits the floor, then stretches as it shoots back up. A bowling ball just lands.\n\nEach ball looks different because it moves differently. In animation, you cannot rely on real physics. You have to draw the weight and softness yourself. The 12 principles are the tricks animators use to do that.\n\nTake five minutes. Think of one cartoon moment that felt real to you even though it was only drawings. Hold that moment in your mind. By the end of this lesson you will be able to name why it worked."},{"type":"read","title":"The first six principles: a closer look","minutes":28,"body":"SQUASH AND STRETCH. Objects change shape to show weight and softness. A ball squashes when it hits the floor and stretches when it moves fast. The rule to remember: the object keeps the same volume. If it gets wider, it gets shorter.\n\nANTICIPATION. A small move in the opposite direction before the main action. A person crouches before jumping. A baseball pitcher winds the arm back before throwing. Anticipation warns the viewer that something is about to happen, so the action feels believable.\n\nSTAGING. Show the idea so clearly that the viewer knows exactly where to look. Use one main thing at a time, a clear silhouette, and enough empty space around it. If everything is busy, nothing is clear.\n\nSTRAIGHT AHEAD AND POSE TO POSE. These are two ways to draw an animation. Straight ahead means you draw frame after frame from the start, which feels spontaneous. Pose to pose means you draw the important poses first, then fill in the frames between. Pose to pose gives you more control, and it is the method we use in this course.\n\nFOLLOW THROUGH AND OVERLAPPING ACTION. When the body stops, loose parts keep moving for a moment, like hair, a scarf, or a tail. They also do not all move at the same speed. This makes the stop feel natural instead of stiff.\n\nSLOW IN AND SLOW OUT. Real things speed up gently and slow down gently. In animation you draw more pictures near the start and the end of a move, and fewer in the middle. The motion eases in and eases out."},{"type":"read","title":"Worked example: one jump, six principles","minutes":20,"body":"Here is the method in action so you can copy the shape of the thinking. Imagine a boy jumping to catch a mango.\n\nFIRST, he bends his knees and swings his arms down. CHOICE: anticipation. EFFECT: we feel the jump coming.\n\nSECOND, in the air his body stretches long, and when he lands his body squashes. CHOICE: squash and stretch. EFFECT: he feels light in the air and heavy on landing.\n\nTHIRD, the camera is placed so the boy and the mango are the clear focus, with a plain sky behind them. CHOICE: staging. EFFECT: your eyes go straight to the action.\n\nFOURTH, after he lands, his shirt and hair keep moving for a moment. CHOICE: follow through. EFFECT: the landing feels soft and real.\n\nNotice the shape of each answer: name the choice, then name the effect. Never say only that it looked good. Say WHAT the animator did and WHAT it did to you."},{"type":"do","title":"Activity: spot the principles","minutes":30,"body":"Try it before the graded activity. Open any animation you can watch legally at home.\n\n1. Pause on three different moments.\n\n2. For each moment, write which of the six principles you can see.\n\n3. In one sentence per moment, say what the animator did and what it did to you.\n\nIt warms up the exact muscle you use below."},{"type":"reflect","title":"Reflection before your activity","minutes":10,"body":"Answer these for yourself before you write your activity. You do not submit them.\n\n1. Which principle do you notice most easily now?\n\n2. Which one is still hard to spot?\n\n3. In the cartoon moment you thought about at the start, can you now name the principle that made it work?"}]$q$::jsonb) on conflict (activity_id) do update set module_id = excluded.module_id, "order" = excluded."order", week = excluded.week, title = excluded.title, competency_code = excluded.competency_code, is_performance_task = excluded.is_performance_task, lesson_goal = excluded.lesson_goal, before_hook = excluded.before_hook, watch_for = excluded.watch_for, video_slot = excluded.video_slot, video_candidate = excluded.video_candidate, video_preview_note = excluded.video_preview_note, video_status = excluded.video_status, video_title = excluded.video_title, video_channel = excluded.video_channel, video_runtime = excluded.video_runtime, video_url = excluded.video_url, after_bridge = excluded.after_bridge, activity_brief = excluded.activity_brief, submission_type = excluded.submission_type, tool = excluded.tool, ai_note = excluded.ai_note, rubric = excluded.rubric, rubric_total = excluded.rubric_total, sections = excluded.sections;
insert into public.activities (activity_id, module_id, "order", week, title, competency_code, is_performance_task, lesson_goal, before_hook, watch_for, video_slot, video_candidate, video_preview_note, video_status, video_title, video_channel, video_runtime, video_url, after_bridge, activity_brief, submission_type, tool, ai_note, rubric, rubric_total, sections) values ($q$G9-A2.2$q$, $q$G9-M2$q$, 2, $q$Week 2$q$, $q$The 12 Principles, Part 2: Check Your Own Frames$q$, null, false, $q$I want you to learn the last six principles and use them to look at your own drawings. You already drew 4 or 5 frames. Now you will see what they already do well and how to push them further.$q$, $q$You already have drawings on your laptop. Before we bring in any software, let us check them like a real animator. Does your first frame make the idea clear? Does your second frame warn us about what is coming? Today you learn the other six principles, then you use all twelve to judge your own work.$q$, $q$["How does the number of drawings change how fast or slow an action feels?","Which pose is pushed further than real life, and why does that help?","Does the movement follow a straight line or a curve?"]$q$::jsonb, $q$Timing or exaggeration in animation, 3 to 8 minutes, English.$q$, $q$Alan Becker, 12 Principles of Animation series, Timing.$q$, $q$Found by web search, not play tested from the build environment. Watch it once before class.$q$, $q$Found by web search. Check before class.$q$, $q$9. Timing - 12 Principles of Animation$q$, $q$Alan Becker$q$, null, $q$https://www.youtube.com/watch?v=BarOk2p38LQ$q$, $q$So the last six are about curves, extra action, speed, push, form, and charm. Arcs make motion natural. Secondary action adds life. Timing sets speed and weight. Exaggeration makes the idea clear. Solid drawing gives shape and volume. Appeal makes people want to look. Now you can judge a drawing with all twelve.$q$, $q$Open your own 4 or 5 drawings. Number them 1, 2, 3, 4 and 5 in the order they play. In 5 to 7 sentences, tell me which principle each frame shows or should show. For example, your getting ready frame shows anticipation. Then pick ONE frame and tell me how you would push it further with exaggeration. Do not redraw anything. Just plan it in words.$q$, $q$Short text$q$, $q$None needed. Look at your drawings on your laptop.$q$, null, $q$[{"criteria":"Names a principle for every frame","points":4},{"criteria":"Explains how each frame shows it","points":3},{"criteria":"Gives a clear exaggeration idea for one frame","points":3}]$q$::jsonb, 10, $q$[{"type":"read","title":"Warm up: why does a slow action feel heavy?","minutes":10,"body":"Imagine two characters lifting a box. One does it in half a second and the box feels light. The other takes three seconds, and the box feels very heavy. The drawings could be exactly the same. Only the speed changed.\n\nThat is the power of the last six principles. They control speed, curves, and how clear and charming your drawing feels."},{"type":"read","title":"The last six principles: a closer look","minutes":28,"body":"ARCS. Most living things move along curved paths, not straight lines. A head turning, an arm swinging, a ball thrown through the air all follow arcs. When you draw the path of a motion as a smooth curve, it looks natural.\n\nSECONDARY ACTION. A smaller action that supports the main action. A character walks (main action) while whistling or swinging a bag (secondary action). It adds personality, but it must never steal attention from the main action.\n\nTIMING. How many drawings you use for an action. More drawings means slower, smoother motion. Fewer drawings means faster, snappier motion. Timing also tells us about weight and mood. A heavy thing moves slowly. A nervous character moves in quick jerks.\n\nEXAGGERATION. Push a pose or an expression further than real life so the idea is clearer and more fun. It is not random. A surprised face with wider eyes and a higher eyebrow reads faster than a realistic one.\n\nSOLID DRAWING. Draw shapes that feel like they have volume, weight, and a back side, not flat paper cutouts. Keep your shapes consistent from one drawing to the next so the character does not change size.\n\nAPPEAL. A design that people enjoy looking at. It does not have to be pretty. It has to be clear, readable, and interesting. A simple balloon with a clear shape and a strong color has appeal."},{"type":"read","title":"Worked example: judging the balloon animation","minutes":20,"body":"Here is how an animator would judge the four frames of a boy popping a balloon. This is a model, not your drawing.\n\nFRAME 1, start pose. The boy stands with the balloon in the middle of the page and nothing else around. PRINCIPLE: staging. The viewer knows where to look.\n\nFRAME 2, getting ready. His arm pulls back and his body leans away. PRINCIPLE: anticipation. We feel the pop coming.\n\nFRAME 3, the pop. The balloon is a spiky burst and his eyes are very wide. PRINCIPLE: exaggeration. The surprise is clear.\n\nFRAME 4, aftermath. His hair and shirt are still settling and a few pieces of the balloon fall. PRINCIPLE: follow through. The action settles instead of stopping dead.\n\nNow notice something. Between frame 2 and frame 3 there is a big jump. That gap will matter a lot in the next lessons."},{"type":"do","title":"Activity: label your frames","minutes":30,"body":"Try it before the graded activity.\n\n1. Open your drawings in the order they play.\n\n2. Write the number of each frame and one principle it shows.\n\n3. Find the frame that is least clear. Ask: which principle would make it stronger?\n\n4. Write one sentence about how you would push that frame further. Do not redraw it. Just plan it."},{"type":"reflect","title":"Reflection before your activity","minutes":10,"body":"Answer these for yourself before you write your activity. You do not submit them.\n\n1. Which of your frames is strongest, and which principle makes it strong?\n\n2. Which frame is weakest, and why?\n\n3. Which principle surprised you the most today?"}]$q$::jsonb) on conflict (activity_id) do update set module_id = excluded.module_id, "order" = excluded."order", week = excluded.week, title = excluded.title, competency_code = excluded.competency_code, is_performance_task = excluded.is_performance_task, lesson_goal = excluded.lesson_goal, before_hook = excluded.before_hook, watch_for = excluded.watch_for, video_slot = excluded.video_slot, video_candidate = excluded.video_candidate, video_preview_note = excluded.video_preview_note, video_status = excluded.video_status, video_title = excluded.video_title, video_channel = excluded.video_channel, video_runtime = excluded.video_runtime, video_url = excluded.video_url, after_bridge = excluded.after_bridge, activity_brief = excluded.activity_brief, submission_type = excluded.submission_type, tool = excluded.tool, ai_note = excluded.ai_note, rubric = excluded.rubric, rubric_total = excluded.rubric_total, sections = excluded.sections;
insert into public.activities (activity_id, module_id, "order", week, title, competency_code, is_performance_task, lesson_goal, before_hook, watch_for, video_slot, video_candidate, video_preview_note, video_status, video_title, video_channel, video_runtime, video_url, after_bridge, activity_brief, submission_type, tool, ai_note, rubric, rubric_total, sections) values ($q$G9-A2.3$q$, $q$G9-M2$q$, 3, $q$Week 3$q$, $q$Keyframes and Inbetweens: Get Your Frames Ready$q$, null, false, $q$I want you to explain what keyframes and inbetweens are, find them in your own work, and get your drawings ready so a computer tool can fill the gaps.$q$, $q$If you show your 4 or 5 drawings one after another, it looks like a slideshow, not an animation. Why? Because real animation has many more pictures. A film shows 24 pictures every second. You only drew 4. The missing pictures have a name: inbetweens. In the next lesson a free AI tool will draw them for you. Today you learn what they are and prepare your files so the tool works properly.$q$, $q$["What is the difference between a key pose and an inbetween?","Why does a big change between two drawings need more inbetweens?","Who usually draws the inbetweens in a real studio?"]$q$::jsonb, $q$Keyframes and inbetweens explained, under 8 minutes, English.$q$, $q$Understanding Keyframes: The Art of Animation Explained (short).$q$, $q$Found by web search, not play tested from the build environment. Watch it once before class.$q$, $q$Found by web search. Check before class.$q$, $q$Understanding Keyframes: The Art of Animation Explained$q$, null, null, $q$https://www.youtube.com/watch?v=-q4m2ys2060$q$, $q$So keyframes are the important poses that mark where a movement starts and ends. Inbetweens are the pictures that fill the gap. The bigger the change between two keyframes, the more inbetweens you need. Your drawings are keyframes. Next we let the computer draw the rest.$q$, $q$Look at your own drawings. In 5 to 7 sentences, do three things. First, list your frames in order and say what each one shows. Second, for each gap between two frames, say if the change is small, medium, or big, and why. Which gap worries you the most? Third, decide how long you want your animation to be (between 3 and 5 seconds) and say why.$q$, $q$Short text$q$, $q$A laptop with your drawings saved as JPG pictures.$q$, null, $q$[{"criteria":"Lists the frames in order with what each shows","points":3},{"criteria":"Rates each gap and gives a reason","points":4},{"criteria":"Chooses a length from 3 to 5 seconds with a reason","points":3}]$q$::jsonb, 10, $q$[{"type":"read","title":"Warm up: the flipbook","minutes":10,"body":"Have you ever made a flipbook in the corner of a notebook? You draw a tiny change on every page, then flip fast and the drawing moves. A good flipbook needs many pages. If you only draw four pages, it jumps.\n\nYour project is a flipbook with only four pages. Today we find out why that jumps, and how to fix it without drawing fifty more pictures."},{"type":"read","title":"Keyframes, breakdowns, and inbetweens","minutes":28,"body":"KEYFRAME. An important pose that defines the start or the end of a movement. In your balloon animation, the start pose and the pop are keyframes. In studios, the lead animator draws the keyframes.\n\nINBETWEENS. The drawings that fill the gaps between keyframes. If there are none, the motion looks jumpy. In a studio, assistants draw them. In a computer program, the software can create them. That is what you will use.\n\nFRAMES PER SECOND. Movies play 24 frames each second. Many hand drawn animations use only 12 drawings each second, which is called animating on twos, because each drawing is shown for two frames. We will use 12 frames per second. It is smooth enough and much less work.\n\nTHE BIG IDEA. The bigger the change between two keyframes, the more inbetweens you need. A small move needs one or two. A big move, like a balloon bursting, needs many. And the more guessing the computer has to do, the more likely it makes a mistake.\n\nDO THE MATH. If your animation is 4 seconds long at 12 frames per second, it has 48 frames. You drew 4 or 5 of them. The tool will create the other 43 or so."},{"type":"read","title":"Worked example: gaps in the balloon animation","minutes":20,"body":"Here is how to rate the gaps. This is a model, not your drawing.\n\nGAP 1, from start pose to getting ready. The arm pulls back a little. The change is SMALL. The computer will do well here.\n\nGAP 2, from getting ready to the pop. The balloon changes from round to a burst of spikes. The change is BIG. The computer may blur this one, because it has to guess a shape that did not exist before.\n\nGAP 3, from the pop to the aftermath. Pieces fall and the boy relaxes. The change is MEDIUM.\n\nSo the animator knows to expect a weak spot at gap 2. Knowing that in advance is a skill. When the result is not perfect, you will already understand why."},{"type":"do","title":"Activity: get your files ready","minutes":30,"body":"This is the setup the computer tool needs. Follow every step and do not skip any.\n\n1. Find your 4 or 5 drawings. They must be JPG pictures. If they are on a phone, send them to your laptop.\n\n2. Make a new folder on your Desktop called my_frames. Copy your pictures into it. Keep your originals safe somewhere else.\n\n3. Put the pictures in the order they should play. Rename them 01.jpg, 02.jpg, 03.jpg, 04.jpg, and 05.jpg if you have a fifth. To rename a file, click it once, press F2, type the new name, and press Enter.\n\n4. Check the file names. In File Explorer, click View, then Show, then File name extensions. Make sure the name is 01.jpg and not 01.jpg.jpg.\n\n5. Look at your pictures. They should be bright, the drawing should fill the picture, and the paper should look the same in every frame. If one picture is much darker, retake it with the same light and from the same distance."},{"type":"reflect","title":"Reflection before your activity","minutes":10,"body":"Answer these for yourself before you write your activity. You do not submit them.\n\n1. Which of your gaps is the biggest?\n\n2. What do you expect the computer to do well, and what do you expect it to get wrong?\n\n3. Is your animation going to be 3, 4, or 5 seconds? Why?"}]$q$::jsonb) on conflict (activity_id) do update set module_id = excluded.module_id, "order" = excluded."order", week = excluded.week, title = excluded.title, competency_code = excluded.competency_code, is_performance_task = excluded.is_performance_task, lesson_goal = excluded.lesson_goal, before_hook = excluded.before_hook, watch_for = excluded.watch_for, video_slot = excluded.video_slot, video_candidate = excluded.video_candidate, video_preview_note = excluded.video_preview_note, video_status = excluded.video_status, video_title = excluded.video_title, video_channel = excluded.video_channel, video_runtime = excluded.video_runtime, video_url = excluded.video_url, after_bridge = excluded.after_bridge, activity_brief = excluded.activity_brief, submission_type = excluded.submission_type, tool = excluded.tool, ai_note = excluded.ai_note, rubric = excluded.rubric, rubric_total = excluded.rubric_total, sections = excluded.sections;
insert into public.activities (activity_id, module_id, "order", week, title, competency_code, is_performance_task, lesson_goal, before_hook, watch_for, video_slot, video_candidate, video_preview_note, video_status, video_title, video_channel, video_runtime, video_url, after_bridge, activity_brief, submission_type, tool, ai_note, rubric, rubric_total, sections) values ($q$G9-A2.4$q$, $q$G9-M2$q$, 4, $q$Week 4$q$, $q$Let the Computer Draw the Inbetweens$q$, null, false, $q$I want you to run a free AI tool on your own drawings, watch what it makes, and judge honestly where it works and where it fails.$q$, $q$Here is something that used to need a whole team of assistants. You give a computer two drawings, and it guesses the pictures in between. The tool is free, it runs on your laptop without internet, and the drawings stay yours. But it is not magic. It guesses. Your job is to find out where it guesses well and where it does not, because that is exactly what a real animator would check.$q$, $q$[]$q$::jsonb, null, null, null, null, null, null, null, null, $q$You now have a moving version of your drawings. Some gaps will look smooth and some will look blurry. That is normal. It tells you which gaps were too big for the tool, and it shows why animators draw inbetweens carefully by hand. Next we use a video editor to add timing, a zoom, and a sound.$q$, $q$Run the tool on your own drawings, then watch the result a few times. In 5 to 7 sentences, tell me: how many drawings you started with and how long your result is, which gap looks best and why, which gap looks worst and why, and which principle from Lessons 1 and 2 would help a hand animator fix that gap. Also say clearly which part the computer made and which part you made.$q$, $q$Short text$q$, $q$The AnimationKit folder from your teacher (on a USB drive), and your numbered JPG pictures.$q$, $q$The computer guesses the inbetween pictures. The ideas, the characters, and every key drawing are yours. In your answer, say clearly which part the AI made and which part you made.$q$, $q$[{"criteria":"Describes the result with real numbers and details","points":3},{"criteria":"Names the best gap and the worst gap and explains why","points":4},{"criteria":"Links the problem to a principle and says what is AI and what is yours","points":3}]$q$::jsonb, 10, $q$[{"type":"read","title":"What the tool does","minutes":10,"body":"The tool is called RIFE. It is a free program that looks at two pictures and guesses what is in the middle. It does this again and again until it has made all the frames you asked for. Your teacher will give you a folder called AnimationKit that already has everything in it. You do not need to install anything or use the internet.\n\nA second small program called ffmpeg then joins all the new pictures into one video file called my_animation.mp4.\n\nThe kit makes all of this happen when you double click one file. You do not type any commands."},{"type":"do","title":"Follow these steps exactly","minutes":30,"body":"Do the steps in order. If something goes wrong, check the table at the end of this section before asking for help.\n\n1. Copy the whole AnimationKit folder from your teacher's USB drive to your Desktop. Do not run it from the USB drive. Do not run it from inside a zip file.\n\n2. Open the AnimationKit folder, then open the folder named put_your_frames_here. If there is a README file in it, you can delete that file.\n\n3. Copy your numbered pictures (01.jpg, 02.jpg, 03.jpg, 04.jpg and so on) from your my_frames folder into put_your_frames_here.\n\n4. Go back to the AnimationKit folder. Double click the file named MAKE_MY_ANIMATION. It may show a .bat at the end.\n\n5. If Windows says Windows protected your PC, click More info, then click Run anyway. This is safe for the file your teacher gave you.\n\n6. A black window opens and asks how many seconds long your animation should be. Type the number you chose in Lesson 3 (3, 4, or 5) and press Enter. If you are not sure, just press Enter and it will use 4 seconds.\n\n7. Wait. You will see Step 1 of 3, Step 2 of 3, and Step 3 of 3. Step 2 is the slow one. On school laptops it can take a few minutes. Do not close the black window. Do not open other programs while you wait.\n\n8. When the window says DONE, press any key. A file called my_animation.mp4 is now in the AnimationKit folder. Double click it and watch your animation. Watch it three times.\n\nTROUBLE? If the window says it cannot find your pictures, check that the files are in put_your_frames_here and that they end in .jpg. If it says a file is missing, tell your teacher that the kit is not complete. If the black window closes by itself, you probably ran it from inside a zip file or from the USB drive, so copy the folder to your Desktop and try again. If Step 2 takes more than 15 minutes, close the window, run it again, and choose 3 seconds."},{"type":"read","title":"How to judge your result","minutes":20,"body":"Watch your animation slowly. You can click the video and press the left and right arrow keys, or just watch it three times. Look for these signs.\n\nGOOD SIGNS. The shapes move smoothly from one pose to the next. The lines stay clean. The motion feels like one movement, not a slideshow.\n\nBAD SIGNS. GHOSTING means you can see two copies of something at the same time. MELTING means lines bend and wobble. FLICKER means the picture jumps in brightness. POP means one shape suddenly appears from nowhere.\n\nWHY IT HAPPENS. The tool has no idea what a boy or a balloon is. It only compares the pictures and guesses how pixels move. When the two pictures are very different, it has to guess a lot, and the guess gets blurry. This is why the biggest gap usually looks the worst.\n\nYou are allowed to be honest. A bad gap is not a failure. It is information. A real animator would use it to decide where to draw an extra pose by hand."},{"type":"reflect","title":"Reflection before your activity","minutes":10,"body":"Answer these for yourself before you write your activity. You do not submit them.\n\n1. Which gap looked best? Which looked worst?\n\n2. Did the worst gap match the gap you were worried about in Lesson 3?\n\n3. What would you want to change in your drawings if you could redraw one frame?"}]$q$::jsonb) on conflict (activity_id) do update set module_id = excluded.module_id, "order" = excluded."order", week = excluded.week, title = excluded.title, competency_code = excluded.competency_code, is_performance_task = excluded.is_performance_task, lesson_goal = excluded.lesson_goal, before_hook = excluded.before_hook, watch_for = excluded.watch_for, video_slot = excluded.video_slot, video_candidate = excluded.video_candidate, video_preview_note = excluded.video_preview_note, video_status = excluded.video_status, video_title = excluded.video_title, video_channel = excluded.video_channel, video_runtime = excluded.video_runtime, video_url = excluded.video_url, after_bridge = excluded.after_bridge, activity_brief = excluded.activity_brief, submission_type = excluded.submission_type, tool = excluded.tool, ai_note = excluded.ai_note, rubric = excluded.rubric, rubric_total = excluded.rubric_total, sections = excluded.sections;
insert into public.activities (activity_id, module_id, "order", week, title, competency_code, is_performance_task, lesson_goal, before_hook, watch_for, video_slot, video_candidate, video_preview_note, video_status, video_title, video_channel, video_runtime, video_url, after_bridge, activity_brief, submission_type, tool, ai_note, rubric, rubric_total, sections) values ($q$G9-A2.5$q$, $q$G9-M2$q$, 5, $q$Weeks 5 to 6$q$, $q$Make It Move: Timing, Zoom, and Sound in OpenShot$q$, null, true, $q$I want you to finish your animation in a free video editor by adding a fade, one hard cut, a zoom, and a sound, then export it and share a link.$q$, $q$You have a moving version of your drawings. Now it needs the final touches that make people feel it. A quick zoom at the big moment. A sound that hits at exactly the right time. A cut that is sudden when it should be sudden. These choices are what turn a clip into an animation with a point of view.$q$, $q$["How does the editor show where a clip starts and ends?","How is a fade different from a hard cut, and when would you use each?","How do you place a sound at exactly the right moment?"]$q$::jsonb, $q$OpenShot beginner tutorial, English.$q$, $q$OpenShot Video Editor Tutorial for Beginners.$q$, $q$Found by web search. Check the runtime. If it is long, tell students to watch only the parts on the timeline, split, and export.$q$, $q$Found by web search. Check before class.$q$, $q$OpenShot Video Editor Tutorial - For Beginners!$q$, null, null, $q$https://www.youtube.com/watch?v=6ORC-Fuppmo$q$, $q$So the editor lets you control time. You set where each part starts, you choose between a fade and a hard cut, you add a zoom to push the eye, and you place a sound where the action lands. Your drawings are only part of it. The finishing is the other part.$q$, $q$Open your my_animation.mp4 in OpenShot and finish your animation. It must have: one fade at the start or the end, one hard cut at your big moment, one zoom, and one sound placed at the right time. Export it as an MP4 and upload it to Google Drive or YouTube (unlisted). Paste the link to your video below. In your reflection, tell me why you chose a fade or a cut where you did.$q$, $q$Link$q$, $q$OpenShot Video Editor (free, offline, from your teacher's USB) and the pop.wav sound in the AnimationKit folder.$q$, $q$The in between frames were made by an AI tool. Everything else is your decision: the drawings, the timing, the fade or cut, the zoom, and the sound. Be ready to explain your choices.$q$, $q$[{"criteria":"Motion looks smooth, and the in between frames are used well","points":5},{"criteria":"Timing follows your plan and fits the length you chose","points":4},{"criteria":"A fade and a hard cut are used on purpose","points":4},{"criteria":"A zoom and a sound are added at the right moment","points":4},{"criteria":"The action is clear and uses at least two principles","points":3}]$q$::jsonb, 20, $q$[{"type":"read","title":"Warm up: why finishing matters","minutes":10,"body":"Two students can have the same drawings and make very different animations. One adds a sound and a zoom at the exact moment of the pop, and the viewer jumps. The other plays the clip with no sound, and nothing happens.\n\nThe finishing choices are what make your animation feel alive. They are your voice as a filmmaker."},{"type":"read","title":"OpenShot in six moves","minutes":28,"body":"You do not need to learn the whole program. You only need six moves. Menu names can look slightly different on your laptop, so look for the same words or the same icons. If you cannot find something, use the OpenShot help or ask your teacher.\n\nMOVE 1, IMPORT. Open OpenShot. Click File, then Import Files, and choose your my_animation.mp4 and the pop.wav sound. They appear in the Project Files panel.\n\nMOVE 2, TIMELINE. Drag my_animation.mp4 onto the first track at the bottom of the screen. Drag pop.wav onto the track below it. You will see them as blocks in a row of time.\n\nMOVE 3, SPLIT FOR A HARD CUT. Move the red playhead line to your big moment (the pop). Right click the video clip and choose Slice, or use the razor tool, to cut the clip into two pieces. A hard cut means one shot ends and the next begins instantly. To make the pop feel sudden, delete about a fifth of a second of the frames just before the pop, then drag the second piece left to close the gap.\n\nMOVE 4, FADE. Right click the start (or end) of the clip and choose Fade, then Fade In (or Fade Out). A fade is a soft dissolve. Use it to start gently or to end calmly.\n\nMOVE 5, ZOOM. Right click the second piece of the clip, choose Animate, then a zoom option such as Zoom In. A quick zoom at the pop pushes the eye toward the action. If you cannot find it, open the Properties and animate Scale X and Scale Y with keyframes.\n\nMOVE 6, SOUND AND EXPORT. Drag pop.wav so its start lines up exactly with the pop. Press Play to check. When you like it, click File, then Export Video, keep the MP4 settings, and click Export Video."},{"type":"read","title":"Worked example: a plan for the balloon animation","minutes":20,"body":"Here is a model plan for a 4 second animation. This is not your animation.\n\nAT 0.0 SECONDS, fade in from black. CHOICE: dissolve. EFFECT: a gentle start.\n\nAT 1.8 SECONDS, the boy pulls back. Nothing else happens. CHOICE: no zoom yet. EFFECT: the viewer feels the build up.\n\nAT 2.0 SECONDS, a hard cut straight to the pop, a quick zoom in over half a second, and the pop sound starts at the same moment. CHOICE: hard cut, zoom, sound. EFFECT: a sudden jolt.\n\nAT 2.5 SECONDS to 4.0 SECONDS, the aftermath settles and the clip ends with a short fade out. CHOICE: dissolve. EFFECT: calm after the shock.\n\nNotice the plan: two soft moments and one hard moment, with the zoom and sound exactly on the hard one. Soft and hard are only meaningful when you use both."},{"type":"do","title":"Activity: plan before you edit","minutes":30,"body":"Before you touch OpenShot, write a four line plan like the worked example.\n\n1. Where is the big moment in your animation, in seconds?\n\n2. Where will you use a fade, and why?\n\n3. Where will you use a hard cut, and why?\n\n4. Where will the zoom and the sound happen?\n\nThen build it. Press Play often and fix the timing until the sound and the picture land together.\n\nTo share it: upload your MP4 to Google Drive, right click it, choose Share, set it to Anyone with the link, and copy the link. Or upload it to YouTube as Unlisted and copy that link. Paste it in the box below."},{"type":"reflect","title":"Reflection before your activity","minutes":10,"body":"Answer these for yourself before you submit. You do not submit them separately.\n\n1. What did the fade do for your animation, and what did the hard cut do?\n\n2. Which principle from Lessons 1 and 2 does your finished animation show best?\n\n3. If you could redraw one frame by hand, which one would you pick and why?"}]$q$::jsonb) on conflict (activity_id) do update set module_id = excluded.module_id, "order" = excluded."order", week = excluded.week, title = excluded.title, competency_code = excluded.competency_code, is_performance_task = excluded.is_performance_task, lesson_goal = excluded.lesson_goal, before_hook = excluded.before_hook, watch_for = excluded.watch_for, video_slot = excluded.video_slot, video_candidate = excluded.video_candidate, video_preview_note = excluded.video_preview_note, video_status = excluded.video_status, video_title = excluded.video_title, video_channel = excluded.video_channel, video_runtime = excluded.video_runtime, video_url = excluded.video_url, after_bridge = excluded.after_bridge, activity_brief = excluded.activity_brief, submission_type = excluded.submission_type, tool = excluded.tool, ai_note = excluded.ai_note, rubric = excluded.rubric, rubric_total = excluded.rubric_total, sections = excluded.sections;
